/*
 * WPJ2 Recomp - RSP microcode dispatcher implementation
 */

#include "rsp_dispatch.hpp"

#include <cstdio>

// aspMain is generated by RSPRecomp into src/rsp/generated/aspMain.c
// Its signature is: RspExitReason aspMain(uint8_t* rdram, uint32_t ucode_addr)
// No extern "C" — RSPRecomp generates C++ code (uses RSP rsp{} etc.).
RspExitReason aspMain(uint8_t* rdram, uint32_t ucode_addr);

namespace wpj2 {

RspExitReason gfx_task_nop(uint8_t* rdram, uint32_t ucode_addr) {
    (void)rdram;
    (void)ucode_addr;
    // GFX tasks are HLE'd by RT64 — we just return Broke so librecomp's
    // run_task considers the SP "done" and fires the SP completion message.
    return RspExitReason::Broke;
}

RspUcodeFunc* get_rsp_microcode(const OSTask* task) {
    switch (task->t.type) {
        case M_AUDTASK:
            // Audio task: dispatch to recompiled aspMain.
            return aspMain;

        case M_GFXTASK:
            // Graphics task: handled by RT64 via send_dl, not by RSP.
            // Returning a nop that breaks immediately keeps librecomp happy.
            return gfx_task_nop;

        default:
            fprintf(stderr, "[WPJ2/RSP] Unknown task type %u — no ucode available\n",
                    task->t.type);
            return nullptr;
    }
}

} // namespace wpj2
